import {AudioEngine,analyseSession,noteName,rmsToDb} from './audio.js';
import {parseScore,createExercise,demoScores} from './score.js';
import {getCoachPlan,getProgress} from './coach.js';
import * as db from './storage.js';
import {readLRCFile,getLyricAt} from './lrc.js';
import {mountMonitor} from './monitor.js';
import {mountJianpu} from './jianpu.js';

const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=Number.isFinite;
const val=(v,suffix='',digits=0)=>finite(v)?`${v.toFixed(digits)}${suffix}`:'—';
const signed=(v,suffix='')=>finite(v)?`${v>0?'+':''}${Math.round(v)}${suffix}`:'—';
const clock=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',practice:'<path d="M4 9v6m4-10v14m4-17v20m4-17v14m4-10v6"/>',songs:'<path d="M9 18V5l11-2v13"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',range:'<path d="M4 18V9m5 9V5m5 13v-7m5 7V3M2 21h20"/>',coach:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',progress:'<path d="M4 3v17h17M7 15l4-5 4 3 5-7"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.practice}</svg>`;
const tabs=[['home','今日練習'],['monitor','音高監看'],['practice','聲音訓練'],['songs','歌曲練習'],['range','我的音域'],['coach','本機教練'],['progress','練習紀錄']];
const kinds={warmup:{name:'每日開嗓',subtitle:'從輕柔的哼鳴開始，讓聲音慢慢醒來。',tip:'用輕柔的「嗯」或唇顫音跟著旋律，避免一開始就用力唱高音。',vowel:'mm'},scale:{name:'母音＋輔音音階',subtitle:'先聽、再唱，找到每個音的中心。',tip:'母音選 a、e、i、o、u，搭配 m、n、b、d、g。從舒適調性開始，注意每個母音的音高。',vowel:'ma'},sustain:{name:'長音穩定度',subtitle:'用均勻的氣息，畫出平穩的聲音線條。',tip:'長音不需要越大聲越好。觀察曲線波動，先維持舒適、連續的氣息。',vowel:'u'},rhythm:{name:'節奏與起音',subtitle:'清楚開始、清楚收尾，讓聲音落在拍點上。',tip:'音符之間清楚收音，才能辨識重複音的起音。裝置延遲會影響結果，可在設定調整。',vowel:'da'},dynamics:{name:'漸強・漸弱',subtitle:'音高保持穩定，讓音量慢慢呼吸。',tip:'每個長音由輕漸響，再慢慢回到輕聲。橘色線為相對音量，並非校準的聲壓分貝。',vowel:'u'}};
const state={route:'home',kind:'scale',root:60,bpm:80,vowel:'ma',minutes:1,sessions:[],scores:[],range:null,settings:{tolerance:25,latencyMs:0,guide:true,metronome:true},song:null,transpose:0,speed:1,audioKind:'synth',audioOffset:0,report:null,reportScore:null,phrase:null,session:null,preview:null,busy:false,planIndex:null,importFile:null};
const engine=new AudioEngine();
let toastTimer,raf,wakeLock,installPrompt,worker;
let decodedCache=null,referenceGeneration=0,preparationGeneration=0,preparingSession=false,activePlan=null,monitorController=null,jianpuController=null;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5200)}
function showModal(title,body){$('modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button data-action="close-modal" aria-label="關閉">×</button></div>${body}`;$('modal').showModal()}
function closeModal(){jianpuController?.destroy();jianpuController=null;$('modal').classList.remove('wide-modal');$('modal').close()}
function storageNotice(){const s=db.getStorageStatus();return s.warning?`<div class="notice orange">${esc(s.warning)}</div>`:''}
function plan(){return getCoachPlan({sessions:state.sessions,range:state.range,goalMinutes:12})}
function allSongs(){return [...state.scores,...demoScores()]}
function pitchRange(score){const ns=score.notes;return `${noteName(Math.min(...ns.map(n=>n.midi)))}–${noteName(Math.max(...ns.map(n=>n.midi)))}`}
function go(route){if(state.busy||state.session||monitorController?.isBusy){toast('請先結束目前的練習，再切換頁面。');return;}stopPreview();state.route=route;history.replaceState(null,'',`#${route}`);render();window.scrollTo({top:0,behavior:'instant'})}
function render(){
  monitorController?.destroy();monitorController=null;
  $('navigation').innerHTML=tabs.map(([r,t])=>`<a class="nav-item ${state.route===r||(state.route==='report'&&r==='practice')?'active':''}" href="#${r}" data-route="${r}" ${state.route===r?'aria-current="page"':''}>${icon(r)}<span>${t}</span>${state.route===r?'<i class="nav-dot"></i>':''}</a>`).join('');
  $('page-title').textContent=tabs.find(([r])=>r===state.route)?.[1]||'練習回顧';
  const views={home:homeView,monitor:()=>'<div id="monitor-root"></div>',practice:practiceView,songs:songsView,range:rangeView,coach:coachView,progress:progressView,report:reportView};
  $('main').innerHTML=storageNotice()+(views[state.route]||homeView)();
  if($('pitch-canvas'))requestAnimationFrame(()=>drawChart());
  if(state.route==='monitor')monitorController=mountMonitor($('monitor-root'));
}
function weekView(progress){return `<div class="week">${progress.week.map(d=>{const date=new Date(d.date+'T12:00:00');const today=d.date===new Date().toLocaleDateString('en-CA');return `<div class="week-day ${today?'today':''}"><span>${d.minutes?val(d.minutes,'m'):''}</span><div class="week-bar"><div class="week-fill" style="height:${Math.min(100,d.minutes/12*100)}%"></div></div><span>${['日','一','二','三','四','五','六'][date.getDay()]}</span></div>`}).join('')}</div>`}
function homeView(){const p=plan(),progress=getProgress(state.sessions);return `
  <div class="greeting"><div><div class="eyebrow">A LITTLE PRACTICE, EVERY DAY</div><h1>今天，也為自己唱一點。</h1><p>不急著唱得完美，先享受聲音進步的每一天。</p></div><div class="date-tag">${new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'short'})}</div></div>
  <section class="hero"><div class="hero-content"><div class="eyebrow">YOUR DAILY VOCAL RITUAL</div><h2>把好聲音，<br>練成你的日常。</h2><p>${esc(state.sessions.length?p.reason:'從輕柔開嗓到音準練習，今天的課表已為你準備好。戴上耳機，留一點時間給自己的聲音。')}</p><div class="hero-meta"><button class="btn light" data-action="start-plan">開始今日練習 <span>↗</span></button><span>◷ 約 ${p.totalMinutes} 分鐘 · ${p.exercises.length} 項練習</span></div></div><div class="hero-art"><img src="./brand-logo.jpg" alt="THE ONE 太陽、海浪與海龜標誌"><span class="hero-art-caption">獨樹一幟・唱出自己的聲音</span></div></section>
  <div class="section-heading"><h2>從這裡，開始發聲</h2><button class="text-button" data-route="practice">探索所有練習 →</button></div><div class="cards-3">
  ${[['warmup','每日輕柔開嗓','用哼鳴喚醒你的聲音','輕柔起步 · 1 分鐘','practice'],['scale','音準與音階','母音＋輔音，穩穩唱對每個音','即時音分 · 曲線回饋','songs'],['range','找到你的音域','認識你的最低音與最高音','舒適發聲 · 30 秒','range']].map(([k,title,desc,meta,i])=>`<button class="card quick-card" data-action="${k==='range'?'range':'exercise'}" data-kind="${k}"><span class="quick-icon">${icon(i)}</span><h3>${title}</h3><p>${desc}</p><div class="card-bottom"><span>${meta}</span><b>↗</b></div></button>`).join('')}</div>
  <div class="bottom-grid"><section class="card"><div class="card-head"><h3>本週的聲音足跡</h3><span class="stat-inline">${val(progress.weeklyMinutes)}<small>分鐘</small></span></div>${weekView(progress)}<p class="hint">${progress.count?`已累積 ${progress.count} 次練習，連續練習 ${progress.streak} 天。`:'你的第一筆練習，會從今天開始。'}</p></section><section class="card"><div class="card-head"><h3>我的聲音地圖</h3><span class="pill">${state.range?'最近測得音域':'尚未測量'}</span></div><div class="range-preview"><strong>${state.range?noteName(state.range.minMidi):'—'}</strong><span>舒適發聲的起點與終點</span><strong>${state.range?noteName(state.range.maxMidi):'—'}</strong></div><div class="piano" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i class="${[0,1,3,4,5].includes(i%7)?'black':''}"></i>`).join('')}</div><button class="text-button" data-route="range">${state.range?'重新認識你的音域':'開始第一次音域測量'} →</button></section></div>
  <div class="install-callout"><span>♧ 音訊在裝置內分析，練習紀錄也留在你的手機。</span><button class="text-button" data-action="settings">加入主畫面 ↗</button></div>`}
function trainingPanel(title,isRange=false){return `<section class="card training-card"><div class="training-top"><h2>${esc(title)}</h2><div class="live-status"><i class="status-light" id="status-light"></i><span id="live-label">準備好時，按下開始</span></div></div><div class="pitch-readout"><div class="pitch-side">${isRange?'本次最低音':'目標音'}<strong id="target-note">—</strong><span id="target-frequency">${isRange?'穩定發聲 0.6 秒後納入':'音高以 A4 = 440 Hz 計算'}</span></div><div class="pitch-main"><div class="note" id="live-note">—</div><div class="cents" id="live-cents">等待你的聲音</div></div><div class="pitch-side">${isRange?'本次最高音':'當前頻率'}<strong id="live-frequency">—</strong><span id="live-confidence">${isRange?'請維持舒適、不擠壓':'Hz · 單一人聲'}</span></div></div><div class="tuner"><div class="tuner-track"></div><div class="tuner-center"></div><div class="tuner-needle" id="tuner-needle"></div></div><div class="tuner-labels"><span>偏低 −50 音分</span><span>中心</span><span>偏高 +50 音分</span></div><div class="chart-shell"><canvas id="pitch-canvas" aria-label="旋律目標與實際人聲音高曲線"></canvas><span class="chart-label" id="chart-label">${isRange?'音域即時曲線':'向右展開的聲音軌跡'}</span></div><div class="chart-legend"><span><i class="target"></i>目標音高</span><span><i></i>你的聲音</span>${state.kind==='dynamics'&&!isRange?'<span><i class="volume"></i>相對音量</span>':''}</div><div class="lyric" id="live-lyric">${isRange?'先唱舒適的音，再慢慢向下、向上探索。':'戴上耳機，讓伴奏不會被麥克風收進來。'}</div><div class="volume-meter" title="麥克風相對音量"><div id="volume-fill"></div></div><div class="progress-track"><div id="session-progress"></div></div><div class="time-label" id="time-label">0:00 / ${isRange?'0:30':clock(getPreparedScore().duration)}</div><div class="transport"><button class="btn" data-action="start-session" id="start-button">● ${isRange?'開始測音域':'開始練習'}</button>${!isRange?'<button class="btn secondary" data-action="preview" id="preview-button">▷ 試聽旋律</button>':''}<button class="btn danger" data-action="stop-session" id="stop-button" hidden>■ 結束並分析</button></div></section>`}
function practiceView(){const k=kinds[state.kind];return `<div class="title-row"><div><div class="eyebrow">MAKE ROOM FOR YOUR VOICE</div><h1>聲音的日常訓練</h1><p>${esc(k.subtitle)}</p></div><span class="pill green">本機即時分析</span></div>${state.planIndex!==null?`<div class="notice">今日課表 ${state.planIndex+1}/${(activePlan||plan()).exercises.length}：${esc((activePlan||plan()).exercises[state.planIndex]?.title||k.name)}。完成後會回顧結果，再進入下一項。</div>`:''}<div class="segmented">${Object.entries(kinds).map(([id,x])=>`<button class="chip ${id===state.kind?'active':''}" data-action="exercise" data-kind="${id}">${x.name}</button>`).join('')}</div><div class="controls-grid"><label class="field">起始音（選舒適音區）<select id="root-select">${Array.from({length:37},(_,i)=>i+43).map(n=>`<option value="${n}" ${n===state.root?'selected':''}>${noteName(n)}</option>`).join('')}</select></label><label class="field">母音＋輔音<select id="vowel-select">${['mm','唇顫音','a','e','i','o','u','ma','me','mi','mo','mu','na','ni','nu','ba','bi','bu','da','di','du','ga','gi','gu'].map(v=>`<option ${v===state.vowel?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">速度（每分鐘拍數）<input id="bpm-input" type="number" min="40" max="180" step="5" value="${state.bpm}"></label><label class="field">練習時間<select id="minutes-select">${[.5,1,2,3,4,5].map(n=>`<option value="${n}" ${n===state.minutes?'selected':''}>${n===.5?'30 秒':n+' 分鐘'}</option>`).join('')}</select></label></div>${trainingPanel(k.name)}`}
function songsView(){if(state.song)return songDetailView();return `<div class="title-row"><div><div class="eyebrow">YOUR SONG, YOUR PRACTICE</div><h1>把喜歡的歌，唱成自己的。</h1><p>簡譜圖片、MP3／M4A 音檔、LRC 歌詞，一起練習。</p></div></div><div class="import-workflow"><button class="card import-step" data-action="jianpu-import"><span class="step-icon">▧</span><span class="eyebrow">01 · MELODY</span><h3>匯入簡譜圖片</h3><p>辨識數字音符，確認後建立旋律。</p><span class="step-link">選擇 JPG／PNG／WebP ↗</span></button><button class="card import-step" data-route="monitor"><span class="step-icon">♫</span><span class="eyebrow">02 · AUDIO</span><h3>MP3／M4A 音檔</h3><p>原唱、伴奏或吉他，保留你的版本。</p><span class="step-link">開啟音檔監看 ↗</span></button><button class="card import-step" data-action="lrc-guide"><span class="step-icon">≋</span><span class="eyebrow">03 · LYRICS</span><h3>LRC 同步歌詞</h3><p>在歌曲中匯入，跟著時間逐句唱。</p><span class="step-link">選擇歌曲加入歌詞 ↗</span></button></div><div class="song-import-extra"><label class="btn ghost small upload-button" for="score-upload">匯入 MusicXML／MIDI／JSON</label><input class="file-input" id="score-upload" type="file" accept=".musicxml,.xml,.mid,.midi,.json,.mxl"><button class="btn ghost small" data-action="reference-import">辨識單音音檔</button></div><div class="section-heading"><h2>我的歌曲</h2><span class="pill">${allSongs().length} 首旋律</span></div><div class="song-grid">${allSongs().map((s,i)=>`<article class="card song-card"><div class="song-cover">${i%2?'♬':'♪'}</div><div class="song-info"><h3>${esc(s.title)}</h3><p>${esc(s.format==='demo'?s.description:s.format==='jianpu-image'?'圖片簡譜':'我的匯入旋律')}<br>${pitchRange(s)} · ${val(s.bpm)} BPM · ${clock(s.duration)}</p><span class="pill ${s.format==='demo'?'green':'orange'}">${s.lyrics?'LRC 已加入':s.format==='demo'?'內建練習':'我的歌曲'}</span></div><button class="btn secondary" data-action="open-song" data-id="${esc(s.id)}" aria-label="練習${esc(s.title)}">↗</button></article>`).join('')}</div>`}

function songDetailView(){const s=state.song;return `<button class="text-button" data-action="back-songs">← 我的歌曲</button><div class="title-row"><div><div class="eyebrow">ONE PHRASE AT A TIME</div><h1>${esc(s.title)}</h1><p>${pitchRange(s)} · ${val(s.bpm)} BPM · ${s.notes.length} 音 · ${clock(s.duration)}</p></div>${s.format!=='demo'?'<button class="btn ghost small" data-action="delete-song">刪除歌曲</button>':'<span class="pill green">練習旋律</span>'}</div>${state.phrase?`<div class="notice">正在重練：${esc(state.phrase.label)} <button class="text-button" data-action="clear-phrase">完整歌曲 →</button></div>`:''}<div class="controls-grid"><label class="field">播放來源<select id="audio-kind"><option value="synth">合成旋律參考音</option>${[['original','原唱音檔'],['backing','伴奏音檔'],['guitar','純吉他音檔']].map(([id,label])=>`<option value="${id}" ${state.audioKind===id?'selected':''}>${label}${s.audioNames?.[id]?' ✓':'（尚未匯入）'}</option>`).join('')}</select></label><label class="field">旋律移調<select id="transpose-select" ${state.audioKind!=='synth'?'disabled':''}>${Array.from({length:25},(_,i)=>i-12).map(n=>`<option value="${n}" ${state.transpose===n?'selected':''}>${n===0?'原調':signed(n)+' 個半音'}</option>`).join('')}</select></label><label class="field">速度<select id="speed-select" ${state.audioKind!=='synth'?'disabled':''}>${[.5,.65,.8,1,1.1,1.2].map(n=>`<option value="${n}" ${state.speed===n?'selected':''}>${Math.round(n*100)}%${n===1?' 原速':''}</option>`).join('')}</select></label><label class="field">樂譜在音檔的起點（秒）<input type="number" id="audio-offset" value="${esc(state.audioOffset)}" min="0" max="1800" step="0.1" ${state.audioKind==='synth'?'disabled':''}></label></div><div class="song-file-row"><div><span class="pill green">音檔</span> <span>${state.audioKind==='synth'?'目前使用合成旋律':esc(s.audioNames?.[state.audioKind]||'選擇 MP3／M4A 音檔')}</span></div>${state.audioKind!=='synth'?'<label class="btn secondary small upload-button" for="audio-upload">匯入 MP3／M4A</label><input class="file-input" id="audio-upload" type="file" accept=".mp3,.m4a,audio/mpeg,audio/mp4,audio/*">':''}</div>${songLyricsView(s)}${trainingPanel('跟著旋律，唱出你的聲音')}`}
function songLyricsView(s){const lyrics=s.lyrics;return `<section class="card song-lyrics"><div class="card-head"><h3>同步歌詞 ${lyrics?'<span class="pill green">LRC</span>':''}</h3><label class="btn ghost small upload-button" for="lrc-upload">${lyrics?'更換 LRC':'＋ 匯入 LRC'}</label><input class="file-input" id="lrc-upload" type="file" accept=".lrc,text/plain"></div>${lyrics?`<div class="lyric-settings"><span>${esc(lyrics.filename||'已匯入歌詞')} · ${lyrics.lines.length} 句</span><label>歌詞提前 <input id="lrc-offset" type="number" min="-10000" max="10000" step="100" value="${esc(lyrics.offsetMs||0)}"> 毫秒</label></div><div class="lrc-line" id="lrc-current">${esc(lyrics.lines[0]?.text||'♪')}</div><div class="lrc-next" id="lrc-next">${esc(lyrics.lines[1]?.text||'')}</div><details class="lrc-details"><summary>查看全部歌詞</summary><div class="lrc-list">${lyrics.lines.map((l,i)=>`<button class="lrc-row" data-action="lyric-phrase" data-index="${i}"><time>${clock(l.time)}</time><span>${esc(l.text||'♪')}</span><b>重練 ↗</b></button>`).join('')}</div></details>`:'<div class="lrc-empty">把歌詞放進來，跟著每一句的時間練唱。</div>'}</section>`}

function rangeView(){return `<div class="title-row"><div><div class="eyebrow">GET TO KNOW YOUR VOICE</div><h1>每個聲音，都有自己的風景。</h1><p>30 秒探索最低與最高穩定音，從舒適的聲音開始。</p></div></div>${state.range?`<section class="card"><div class="card-head"><h3>最近測得的音域</h3><span class="pill">${new Date(state.range.createdAt).toLocaleDateString('zh-TW')}</span></div><div class="range-big"><div><span>最低穩定音</span><strong>${noteName(state.range.minMidi)}</strong></div><span class="range-dash">—</span><div><span>最高穩定音</span><strong>${noteName(state.range.maxMidi)}</strong></div></div><p class="hint" style="text-align:center">${state.range.maxMidi-state.range.minMidi} 個半音 · 這是本次實測範圍，並非專業聲部分類。</p></section><div style="height:18px"></div>`:''}<div class="notice">先以舒服音高唱「啊」或「嗚」，再慢慢往低、往高探索。每個音穩定維持至少 0.6 秒才納入紀錄，避免短暫雜訊被算成極限音。</div>${trainingPanel('認識我的音域',true)}`}
function coachView(){const p=plan();return `<div class="title-row"><div><div class="eyebrow">A PLAN THAT GROWS WITH YOU</div><h1>今天，練對你有幫助的。</h1><p>從自己的紀錄出發，讓每一次練習更有方向。</p></div></div><div class="coach-banner"><div class="coach-avatar">✦</div><div><span class="pill green" style="margin-bottom:12px">免費本機教練</span><h2>${esc(p.headline)}</h2><p>${esc(p.reason)}</p></div></div>${p.weaknesses.length?`<div class="weaknesses">${p.weaknesses.map(w=>`<span class="weakness" title="${esc(w.detail)}">◎ ${esc(w.label)}</span>`).join('')}</div>`:''}<div class="section-heading"><h2>你的今日課表</h2><span class="pill">約 ${p.totalMinutes} 分鐘</span></div><div class="plan-list">${p.exercises.map((x,i)=>`<div class="card plan-item"><span class="plan-number">${String(i+1).padStart(2,'0')}</span><div class="plan-body"><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p></div><span class="plan-time">${x.minutes} 分鐘</span><button class="btn secondary small" data-action="plan-item" data-index="${i}">開始 ↗</button></div>`).join('')}</div><div class="section-heading"><h2>適合接著練的旋律</h2><button class="text-button" data-route="range">${state.range?'更新音域':'先測我的音域'} →</button></div><div class="song-grid">${p.songs.map(s=>`<div class="card"><h3>${esc(s.title)}</h3><p class="hint">${esc(s.reason)}</p><button class="text-button" data-action="recommended-song" data-id="${s.id}" data-transpose="${s.transpose||0}">準備練習 →</button></div>`).join('')}</div>`}
function progressView(){const p=getProgress(state.sessions);return `<div class="title-row"><div><div class="eyebrow">EVERY NOTE COUNTS</div><h1>你的進步，都有跡可循。</h1><p>累積的每一分鐘，都在讓聲音更熟悉自己。</p></div><button class="btn ghost small" data-action="export">匯出備份 ↓</button></div><div class="metrics">${metric('總練習次數',p.count,'次')}${metric('累積練習',p.totalMinutes,'分鐘')}${metric('本週練習',p.weeklyMinutes,'分鐘')}${metric('連續練習',p.streak,'天')}</div><section class="card"><div class="card-head"><h3>最近七天</h3><span class="pill">目標：每天約 12 分鐘</span></div>${weekView(p)}</section><div class="section-heading"><h2>練習足跡</h2><span class="pill">只保存分析數據</span></div><section class="card">${state.sessions.length?state.sessions.map(s=>`<div class="history-row"><div><strong>${esc(s.title||'聲音練習')}</strong><p>${new Date(s.createdAt).toLocaleString('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${clock(s.duration)} · 發聲 ${val(s.coverage,'%')}</p></div><div class="history-score">${val(s.meanAbsCents,' 音分')}<br><button class="text-button" data-action="history-report" data-id="${esc(s.id)}">查看 →</button></div></div>`).join(''):'<div class="empty"><span class="empty-symbol">♩</span>還沒有練習紀錄。<br>從一分鐘的開嗓開始，留下你的第一條聲音曲線。</div>'}</section>`}
function metric(label,value,unit,sub=''){return `<div class="metric"><div class="label">${esc(label)}</div><div class="value">${val(value)}<small> ${esc(unit)}</small></div>${sub?`<div class="sub">${esc(sub)}</div>`:''}</div>`}
function reportView(){const r=state.report;if(!r)return '<div class="empty">尚未有練習結果。</div>';const sufficient=r.voicedSeconds>=2&&r.coverage>=10;return `<div class="title-row"><div><div class="eyebrow">A MOMENT TO LISTEN BACK</div><h1>${sufficient?'每一次唱，都更了解自己。':'這次的聲音資料還不夠。'}</h1><p>${esc(r.title||'練習回顧')} · ${clock(r.duration)} · ${r.partial?'提前結束':'本次完成'}</p></div><span class="pill ${sufficient?'green':'orange'}">${sufficient?'已完成分析':'需要更多發聲'}</span></div>${!sufficient?'<div class="notice orange">收到的人聲較少，數據不適合用來判斷能力。請確認麥克風權限、戴上耳機，並靠近麥克風重新練習。</div>':''}<div class="metrics">${metric('平均音準偏差',r.meanAbsCents,'音分','越接近 0，越靠近目標旋律')}${metric('長音波動',r.stabilityCents,'音分','扣除每音固定偏差後的波動')}${metric('起音偏移',r.rhythmMs,'毫秒',finite(r.rhythmMs)?(r.rhythmMs>60?'起音多偏晚，可能拖拍':r.rhythmMs< -60?'起音多偏早，可能搶拍':'大致接近拍點'):'未辨識到足夠起音')}${metric('發聲覆蓋率',r.coverage,'%','沒有發聲的區段不會得到音準分數')}</div><div class="badge-row"><span class="pill green">音準達標率 ${val(r.accuracy,'%')}</span><span class="pill">容許 ±${r.toleranceCents||state.settings.tolerance} 音分</span></div><div class="section-heading"><h2>一句一句，練得更穩</h2><span class="pill">${r.phrases?.length||0} 個樂句</span></div><div class="phrase-list">${[...(r.phrases||[])].sort((a,b)=>(b.meanAbsCents??1000)-(a.meanAbsCents??1000)).map((p,i)=>`<div class="phrase-row"><span class="phrase-id">${esc(p.id)}</span><div class="phrase-main"><h3>${esc(p.label.slice(0,65))}</h3><p>${clock(p.start)}–${clock(p.end)} · 發聲 ${val(p.coverage,'%')} · 起音 ${signed(p.rhythmMs,'ms')}</p></div><span class="phrase-score">${val(p.meanAbsCents,' 音分')}</span>${state.reportScore?`<button class="btn secondary small" data-action="retry-phrase" data-id="${esc(p.id)}">重練</button>`:''}</div>`).join('')||'<div class="empty">這次沒有可比較的旋律樂句。</div>'}</div><div class="report-actions">${state.reportScore?'<button class="btn" data-action="retry">再練一次 ↗</button>':''}${state.planIndex!==null&&state.planIndex+1<(activePlan||plan()).exercises.length?'<button class="btn secondary" data-action="next-plan">課表下一項 →</button>':''}<button class="btn ghost" data-route="coach">查看教練建議</button><button class="btn ghost" data-route="home">回到今日練習</button></div>`}

function getPreparedScore(){
  let s=state.route==='songs'&&state.song?state.song:createExercise({kind:state.kind,root:state.root,bpm:state.bpm,vowel:state.vowel,minutes:state.minutes});
  const transpose=state.route==='songs'?state.transpose:0,speed=state.route==='songs'?state.speed:1;
  let notes=s.notes.map(n=>({...n,midi:n.midi+transpose,start:n.start/speed,duration:n.duration/speed}));
  let offset=0;
  if(state.route==='songs'&&state.phrase){notes=notes.filter(n=>String(n.phrase)===String(state.phrase.id));offset=Math.min(...notes.map(n=>n.start));notes=notes.map(n=>({...n,start:n.start-offset}));}
  return {...s,notes,duration:Math.max(...notes.map(n=>n.start+n.duration))+0.3,originalOffset:offset,speed};
}
function currentNote(notes,t){return notes.find(n=>t>=n.start&&t<n.start+n.duration)||null}
function hasOverlap(notes){let end=-1;return [...notes].sort((a,b)=>a.start-b.start).some(n=>{const overlap=n.start<end-.02;end=Math.max(end,n.start+n.duration);return overlap})}
function lockControls(lock){document.querySelectorAll('#main select,#main input,#main .segmented button,#main [data-action="back-songs"],#main [data-action="delete-song"]').forEach(el=>el.disabled=lock);if(!lock&&state.route==='songs'&&state.audioKind!=='synth'){['transpose-select','speed-select'].forEach(id=>{if($(id))$(id).disabled=true})}if($('start-button')){$('start-button').hidden=lock;$('start-button').disabled=lock}if($('preview-button'))$('preview-button').hidden=lock;if($('stop-button'))$('stop-button').hidden=!lock}
async function startSession(){
  if(state.busy||state.session)return;const preparation=++preparationGeneration;preparingSession=true;stopPreview();state.busy=true;lockControls(true);$('live-label').textContent='正在準備麥克風…';
  const isRange=state.route==='range',score=isRange?{title:'音域探索',notes:[],duration:30,bpm:60}:getPreparedScore();
  try{
    await engine.ensureContext();if(preparation!==preparationGeneration)return;
    if(!isRange&&hasOverlap(score.notes))throw new Error('所選聲部包含重疊音符。請重新匯入並選擇單一人聲旋律聲部或音軌，再開始評分。');
    let audioBuffer;
    if(state.route==='songs'&&state.audioKind!=='synth'){
      const blob=await db.getAudio(state.song.id,state.audioKind);if(preparation!==preparationGeneration)return;if(!blob)throw new Error('請先匯入這個播放來源的音檔。');
      const key=`${state.song.id}/${state.audioKind}/${state.song.audioNames?.[state.audioKind]}`;
      if(decodedCache?.key===key)audioBuffer=decodedCache.buffer;else {const bytes=await blob.arrayBuffer();if(preparation!==preparationGeneration)return;audioBuffer=await engine.context.decodeAudioData(bytes);if(preparation!==preparationGeneration)return;decodedCache={key,buffer:audioBuffer};}
      const offset=state.audioOffset+score.originalOffset;if(offset>=audioBuffer.duration)throw new Error('音檔起點超過檔案長度，請調整起點位置。');
      if(audioBuffer.duration-offset<score.duration-1)throw new Error('音檔剩餘長度不足以涵蓋這份旋律譜，請換成相同版本或調整起點。');
    }
    if(preparation!==preparationGeneration)return;await engine.start(onFrame);if(preparation!==preparationGeneration)return;
    if(!engine.running)throw new Error('麥克風啟動已取消，請重試。');
    const now=performance.now()/1000,start=now+3;
    state.session={score,notes:score.notes,duration:score.duration,frames:[],start,isRange,kind:isRange?'range':state.route==='songs'?'song':state.kind,nextNote:0,nextBeat:-3,rangeBins:new Map(),rangeRun:null,source:null,sourceGain:null};
    if(audioBuffer){const src=engine.context.createBufferSource(),gain=engine.context.createGain();gain.gain.value=.65;src.buffer=audioBuffer;src.connect(gain);gain.connect(engine.context.destination);src.start(engine.context.currentTime+3,state.audioOffset+score.originalOffset);state.session.source=src;state.session.sourceGain=gain;}
    preparingSession=false;state.busy=false;$('status-light').classList.add('live');tick();
    if(navigator.wakeLock)navigator.wakeLock.request('screen').then(lock=>{if(state.session&&preparation===preparationGeneration)wakeLock=lock;else lock.release().catch(()=>{})}).catch(()=>{});
  }catch(error){if(preparation!==preparationGeneration)return;preparingSession=false;engine.stop();state.busy=false;lockControls(false);$('live-label').textContent='尚未開始';const message=error.name==='NotAllowedError'?'麥克風未獲允許。請在 Safari／Chrome 的網站設定允許麥克風，再試一次。':error.name==='NotFoundError'?'找不到麥克風，請確認裝置有可用的音訊輸入。':error.name==='NotReadableError'?'麥克風可能正被其他程式使用，請關閉其他錄音程式再試。':error.message;toast(message)}
}
function cancelPreparation(message='已取消麥克風準備，這次沒有建立練習紀錄。'){if(!preparingSession)return false;preparationGeneration++;preparingSession=false;engine.stop();state.busy=false;lockControls(false);if($('live-label'))$('live-label').textContent='已取消';if(message)toast(message);return true;}
function onFrame(frame){const s=state.session;if(!s)return;const time=frame.time-s.start;if(time<0)return;s.frames.push({...frame,time});const note=currentNote(s.notes,time-state.settings.latencyMs/1000);let cents=finite(frame.midi)?(frame.midi-(note?.midi??Math.round(frame.midi)))*100:null;
  if($('live-note')){$('live-note').textContent=finite(frame.midi)?noteName(frame.midi):'—';$('live-cents').textContent=finite(cents)?`${signed(cents)} 音分${note?cents>state.settings.tolerance?' · 偏高':cents< -state.settings.tolerance?' · 偏低':' · 接近目標':' · 相對最近音名'}`:'尚未偵測到清晰人聲';$('live-cents').style.color=note&&finite(cents)&&Math.abs(cents)>state.settings.tolerance?'var(--pitch-warning, var(--orange, #b17a52))':'var(--pitch-good, var(--sage, #64815b))';$('tuner-needle').style.left=`calc(${50+Math.max(-50,Math.min(50,cents??0))}% - 6px)`;$('volume-fill').style.width=`${Math.min(100,Math.max(0,(rmsToDb(frame.rms)+60)/60*100))}%`;
    if(s.isRange){updateRange(s,frame,time);const range=getRange(s);$('target-note').textContent=range?noteName(range.minMidi):'—';$('live-frequency').textContent=range?noteName(range.maxMidi):'—';}
    else{$('target-note').textContent=note?noteName(note.midi):'休息';$('live-frequency').textContent=val(frame.frequency,'',1);$('live-confidence').textContent=finite(frame.midi)?`Hz · 清晰度 ${Math.round(frame.confidence*100)}%`:'Hz · 單一人聲';}
  }
}
function updateRange(s,f,t){if(!finite(f.midi)||f.confidence<.9){s.rangeRun=null;return;}const midi=Math.round(f.midi);if(!s.rangeRun||s.rangeRun.midi!==midi||t-s.rangeRun.last>.15)s.rangeRun={midi,start:t,last:t};else s.rangeRun.last=t;if(t-s.rangeRun.start>=.6)s.rangeBins.set(midi,true)}
function getRange(s){const values=[...s.rangeBins.keys()];return values.length?{minMidi:Math.min(...values),maxMidi:Math.max(...values)}:null}
function tick(){const s=state.session;if(!s)return;const t=performance.now()/1000-s.start;if(t>=s.duration){finishSession(false);return;}const beat=60/s.score.bpm;
  while(s.nextBeat*beat<t+.15){const bt=s.nextBeat*beat;if(bt>=t-.1&&(state.settings.metronome||s.nextBeat<0))engine.click(s.nextBeat%4===0,Math.max(0,bt-t));s.nextBeat++;}
  while(s.nextNote<s.notes.length&&s.notes[s.nextNote].start<t+.22){const n=s.notes[s.nextNote++];if(!s.source&&state.settings.guide&&n.start+n.duration>t)engine.tone(n.midi,n.duration,Math.max(0,n.start-t),.11,'sine');}
  if($('live-label')){$('live-label').textContent=t<0?`準備，${Math.ceil(-t)}…`:'正在聆聽你的聲音';$('live-lyric').textContent=t<0?'跟著倒數，準備開始。':s.isRange?'每個音穩定停留，慢慢探索舒適範圍。':currentNote(s.notes,t)?.lyric||'放鬆，換一口氣。';$('time-label').textContent=`${clock(t)} / ${clock(s.duration)}`;$('session-progress').style.width=`${Math.max(0,t/s.duration*100)}%`;}
  drawChart();raf=requestAnimationFrame(tick);
}
function releaseSession(s){cancelAnimationFrame(raf);engine.stop();if(s?.source)try{s.source.stop();s.source.disconnect();s.sourceGain.disconnect()}catch{}if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null}}
async function finishSession(partial=true){const s=state.session;if(!s||state.busy)return;state.busy=true;state.session=null;releaseSession(s);const duration=Math.max(0,Math.min(s.duration,performance.now()/1000-s.start));
  try{
    if(duration<1){state.busy=false;lockControls(false);$('live-label').textContent='已取消';toast('已停止，這次沒有建立練習紀錄。');return;}
    if(s.isRange){const range=getRange(s);if(!range){state.busy=false;lockControls(false);$('live-label').textContent='資料不足';toast('未收到穩定超過 0.6 秒的人聲。請靠近麥克風、保持安靜，重新測量。');return;}state.range={...range,createdAt:new Date().toISOString()};await db.setSetting('range',state.range);state.busy=false;render();toast(`本次音域 ${noteName(range.minMidi)}–${noteName(range.maxMidi)}，已保存。`);return;}
    const notes=s.notes.filter(n=>n.start<duration).map(n=>({...n,duration:Math.min(n.duration,duration-n.start)}));
    const report=analyseSession({frames:s.frames,notes,duration,latencyMs:state.settings.latencyMs,toleranceCents:state.settings.tolerance});
    Object.assign(report,{title:s.score.title,kind:s.kind,partial,createdAt:new Date().toISOString(),scoreId:state.song&&s.kind==='song'?state.song.id:null,songSettings:s.kind==='song'?{transpose:state.transpose,speed:state.speed,audioKind:state.audioKind,audioOffset:state.audioOffset}:null,exercise:s.kind!=='song'?{kind:s.kind,root:state.root,bpm:state.bpm,vowel:state.vowel,minutes:state.minutes}:null});
    if(s.kind==='dynamics')report.dynamicsError=dynamicsError(s.frames.map(f=>({...f,time:f.time-state.settings.latencyMs/1000})),notes);
    report.id=await db.saveSession(report);state.sessions=await db.getSessions(500);state.report=report;state.reportScore=s.score;state.busy=false;state.route='report';render();window.scrollTo({top:0,behavior:'instant'});
  }catch(error){state.busy=false;render();toast(`分析或保存未完成：${error.message}`)}
}
function dynamicsError(frames,notes){const errors=[];for(const n of notes){const f=frames.filter(f=>finite(f.midi)&&f.rms>.005&&f.time>=n.start+.12&&f.time<n.start+n.duration-.1);if(f.length<8)continue;const levels=f.map(f=>rmsToDb(f.rms)),mean=levels.reduce((a,b)=>a+b)/levels.length;f.forEach((f,i)=>{const x=(f.time-n.start)/n.duration,target=12*(1-Math.abs(2*x-1))-6;errors.push((levels[i]-mean-target)**2)})}return errors.length?Math.sqrt(errors.reduce((a,b)=>a+b)/errors.length):null}
async function preview(){if(state.session||state.busy)return;if(state.preview){stopPreview();return;}try{await engine.ensureContext();const score=getPreparedScore();if(hasOverlap(score.notes))throw new Error('旋律中有重疊音符，請選擇單一旋律聲部。');const start=performance.now()/1000;state.preview={score,start,index:0};if($('preview-button'))$('preview-button').textContent='■ 停止試聽';const loop=()=>{const p=state.preview;if(!p)return;const t=performance.now()/1000-p.start;while(p.index<p.score.notes.length&&p.score.notes[p.index].start<t+.2){const n=p.score.notes[p.index++];engine.tone(n.midi,n.duration,Math.max(0,n.start-t),.16)}drawChart();if(t>p.score.duration)stopPreview();else raf=requestAnimationFrame(loop)};loop();}catch(e){toast(e.message)}}
function stopPreview(){if(!state.preview)return;state.preview=null;cancelAnimationFrame(raf);engine.stopTones();if($('preview-button'))$('preview-button').textContent='▷ 試聽旋律';drawChart()}
function drawChart(){const canvas=$('pitch-canvas');if(!canvas)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=Math.min(2,window.devicePixelRatio||1);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height;ctx.clearRect(0,0,w,h);const plotStyle=getComputedStyle(canvas),plotColor=(name,fallback)=>plotStyle.getPropertyValue(name).trim()||fallback;ctx.fillStyle=plotColor('--plot-surface','#f6f8ef');ctx.fillRect(0,0,w,h);
  if(state.route==='songs')updateSongLyrics(state.session?performance.now()/1000-state.session.start:state.preview?performance.now()/1000-state.preview.start:0,state.session?.score||state.preview?.score||getPreparedScore());
  const s=state.session,p=state.preview,score=s?.score||p?.score||(state.route==='range'?{notes:[]}:getPreparedScore()),frames=s?.frames||[],notes=score.notes;const t=s?performance.now()/1000-s.start:p?performance.now()/1000-p.start:0;const windowSeconds=state.route==='range'?12:Math.max(7,Math.min(14,60/(score.bpm||80)*12));const start=Math.max(0,t-windowSeconds*.36),end=start+windowSeconds;
  const visible=notes.filter(n=>n.start+n.duration>=start&&n.start<=end);const pitches=[...visible.map(n=>n.midi),...frames.filter(f=>f.time>=start&&f.time<=end&&finite(f.midi)).map(f=>f.midi)];const low=pitches.length?Math.floor(Math.min(...pitches))-2:state.root-2,high=pitches.length?Math.ceil(Math.max(...pitches))+2:state.root+10;const left=38,right=12,top=24,bottom=24;const x=t=>left+(t-start)/(end-start)*(w-left-right),y=m=>h-bottom-(m-low)/(high-low)*(h-top-bottom);
  ctx.font='9px ui-sans-serif';ctx.textBaseline='middle';for(let n=low;n<=high;n++){ctx.strokeStyle=n%12===0?plotColor('--plot-grid-strong','#d7dfcc'):plotColor('--plot-grid','#e6ebdf');ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(left,y(n));ctx.lineTo(w-right,y(n));ctx.stroke();if((high-low)<18||n%2===0){ctx.fillStyle=plotColor('--plot-label','#8c9b7b');ctx.fillText(noteName(n),5,y(n))}}
  const beat=60/(score.bpm||80);for(let bt=Math.ceil(start/beat)*beat;bt<=end;bt+=beat){ctx.strokeStyle=plotColor('--plot-grid','#e0e7d6');ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(x(bt),top);ctx.lineTo(x(bt),h-bottom);ctx.stroke()}
  for(const n of visible){ctx.fillStyle=plotColor('--plot-target','#bdcea6');const xx=Math.max(left,x(n.start)),width=Math.min(w-right,x(n.start+n.duration))-xx;ctx.beginPath();ctx.roundRect(xx,y(n.midi)-4,Math.max(1,width),8,3);ctx.fill()}
  ctx.strokeStyle=plotColor('--plot-trace','#436b52');ctx.lineWidth=2;ctx.beginPath();let prev=null;for(const f of frames){if(f.time<start||f.time>end||!finite(f.midi)){prev=null;continue}const ft=f.time-state.settings.latencyMs/1000;if(prev&&f.time-prev.time<.16&&Math.abs(f.midi-prev.midi)<5)ctx.lineTo(x(ft),y(f.midi));else ctx.moveTo(x(ft),y(f.midi));prev=f}ctx.stroke();
  if(s?.kind==='dynamics'){ctx.beginPath();ctx.strokeStyle=plotColor('--plot-volume','#c58a59');ctx.lineWidth=1.5;prev=null;for(const f of frames){if(f.time<start||f.time>end||f.rms<=0){prev=null;continue}const yy=h-bottom-Math.max(0,Math.min(1,(rmsToDb(f.rms)+60)/60))*(h-top-bottom);if(prev)ctx.lineTo(x(f.time),yy);else ctx.moveTo(x(f.time),yy);prev=f}ctx.stroke()}
  if(s||p){ctx.strokeStyle=plotColor('--plot-cursor','#cf956a');ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(x(Math.max(0,t)),top-8);ctx.lineTo(x(Math.max(0,t)),h-bottom);ctx.stroke();ctx.setLineDash([])}
  ctx.fillStyle=plotColor('--plot-label','#8b997d');ctx.textBaseline='bottom';for(let sec=Math.ceil(start);sec<=end;sec+=2)ctx.fillText(clock(sec),x(sec),h-5);
}

function settingsModal(){showModal('練功房設定',`<h3 style="margin-top:0">加入手機主畫面</h3><p>iPhone：Safari → 分享 → 加入主畫面。<br>Android：Chrome → 選單 → 安裝應用程式。</p>${installPrompt?'<button class="btn secondary small" data-action="install">安裝練功房 ↗</button>':''}<h3>音準與裝置</h3><label class="field">音準達標容許範圍<select id="tolerance-setting">${[10,15,20,25,30,40,50].map(n=>`<option value="${n}" ${n===state.settings.tolerance?'selected':''}>±${n} 音分</option>`).join('')}</select></label><label class="field">延遲補償：<span id="latency-label">${state.settings.latencyMs} 毫秒</span><input type="range" id="latency-setting" min="-300" max="500" step="10" value="${state.settings.latencyMs}"></label><label class="check-label"><input type="checkbox" id="guide-setting" ${state.settings.guide?'checked':''}> 播放旋律參考音</label><label class="check-label"><input type="checkbox" id="metronome-setting" ${state.settings.metronome?'checked':''}> 播放節拍器</label><h3>本機資料</h3><div class="settings-actions"><button class="btn secondary small" data-action="export">匯出歌曲與摘要 ↓</button><label class="btn ghost small upload-button" for="backup-upload">還原備份 ↑</label><input class="file-input" id="backup-upload" type="file" accept=".json,application/json"></div><p>此備份不含音檔；音高監看的錄音可在該頁另存。</p><button class="btn" data-action="close-modal" style="width:100%;margin-top:15px">完成</button>`)}

function setExercise(kind,options={}){if(state.session||state.busy)return;stopPreview();state.kind=kind in kinds?kind:'scale';state.vowel=options.vowel||kinds[state.kind].vowel;if(options.root!==undefined)state.root=options.root;if(options.bpm!==undefined)state.bpm=options.bpm;state.minutes=options.minutes||1;state.planIndex=options.planIndex??null;state.route='practice';render();window.scrollTo({top:0,behavior:'instant'})}
function startPlan(index=0,continuePlan=false){if(!continuePlan||!activePlan)activePlan=plan();const item=activePlan.exercises[index];if(!item)return;setExercise(item.kind,{...item,planIndex:index})}
function openSong(id,transpose=0){const s=allSongs().find(x=>x.id===id);if(!s){toast('找不到這首歌曲，請重新匯入旋律譜。');return;}state.song=s;state.phrase=null;state.transpose=transpose;state.speed=1;state.audioKind='synth';state.audioOffset=finite(s.audioOffset)?Math.max(0,Math.min(1800,s.audioOffset)):0;decodedCache=null;go('songs')}
function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportBackup(){try{downloadJson(await db.exportData(),`獨樹一幟練功房備份-${new Date().toLocaleDateString('en-CA')}.json`);toast('已匯出備份。備份不含音檔，請另外保留原始音檔。')}catch(e){toast(e.message)}}
function openJianpu(){showModal('簡譜圖片辨識','<div id="jianpu-root"></div>');$('modal').classList.add('wide-modal');jianpuController=mountJianpu($('jianpu-root'),{onCancel:closeModal,onSave:async score=>{try{score.id=await db.saveScore(score);state.scores=await db.getScores();closeModal();openSong(score.id);toast('簡譜已保存，接著可加入 MP3／M4A 和 LRC。')}catch(e){toast(e.message)}}})}
function groupNotesByLyrics(song){if(!song.lyrics?.lines?.length)return;let previous=null;song.notes=song.notes.map(n=>{const lyric=getLyricAt(song.lyrics.lines,n.start+(song.audioOffset||0),song.lyrics.offsetMs||0),phrase=lyric?lyric.index+1:'前奏',first=phrase!==previous;previous=phrase;return {...n,phrase,lyric:first?(lyric?.text||'前奏'):''}})}
async function importSongLyrics(file){if(!file||!state.song)return;try{const lyrics=await readLRCFile(file);if(state.song.format==='demo')state.song={...state.song,id:'my-'+state.song.id,format:'imported-demo'};state.song.lyrics=lyrics;groupNotesByLyrics(state.song);await db.saveScore(state.song);state.scores=await db.getScores();state.phrase=null;render();toast(`已加入 ${lyrics.lines.length} 句同步歌詞。`)}catch(e){toast(e.message)}}
function updateSongLyrics(t,score){const lyrics=state.song?.lyrics;if(!lyrics?.lines||!$('lrc-current'))return;const time=Math.max(0,t+(score.originalOffset||0))*(score.speed||1)+state.audioOffset;const active=getLyricAt(lyrics.lines,time,lyrics.offsetMs||0),index=active?.index??-1;const label=active?.text||'♪';$('lrc-current').textContent=label;$('lrc-next').textContent=lyrics.lines[index+1]?.text||'';if($('live-lyric')&&t>=0)$('live-lyric').textContent=label;document.querySelectorAll('.lrc-row').forEach((el,i)=>el.classList.toggle('active',i===index));}
function practiceLyric(index){const lyric=state.song?.lyrics?.lines[index];if(!lyric)return;const notes=state.song.notes.filter(n=>Number(n.phrase)===index+1);if(!notes.length){toast('這句歌詞沒有對應到譜面音符，請調整樂譜起點或歌詞偏移。');return;}state.phrase={id:index+1,label:lyric.text,start:Math.min(...notes.map(n=>n.start)),end:Math.max(...notes.map(n=>n.start+n.duration))};stopPreview();render();$('pitch-canvas')?.scrollIntoView({behavior:'smooth',block:'center'});}
let parsedImport=null;
async function importScore(file,options={}){if(!file)return;try{state.importFile=file;parsedImport=await parseScore(file,options);if(parsedImport.duration>3600)throw new Error('這份樂譜超過 60 分鐘，請先裁切成要練的段落。');showImportModal(parsedImport)}catch(e){toast(e.message)}}
function showImportModal(s){const part=s.parts?.find(p=>p.id===s.selectedPart);const overlap=hasOverlap(s.notes);showModal('選擇要唱的旋律',`<p>檔案：${esc(state.importFile.name)}。請選擇主唱聲部，避免把鋼琴和弦當成人聲旋律。</p><label class="field">歌曲名稱<input id="import-title" maxlength="160" value="${esc(s.title)}"></label>${s.parts?.length?`<label class="field">MusicXML 聲部<select id="import-part">${s.parts.map(p=>`<option value="${esc(p.id)}" ${p.id===s.selectedPart?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${part?.voices?.length?`<label class="field">旋律 Voice<select id="import-voice">${part.voices.map(v=>`<option value="${esc(v)}" ${String(v)===String(s.selectedVoice)?'selected':''}>Voice ${esc(v)}</option>`).join('')}</select></label>`:''}`:''}${s.tracks?.length?`<label class="field">MIDI 音軌<select id="import-track">${s.tracks.map(t=>`<option value="${t.index}" ${t.index===s.selectedTrack?'selected':''}>${esc(t.name)} · ${t.noteCount} 音 · ${noteName(t.low)}–${noteName(t.high)}</option>`).join('')}</select></label>`:''}<div class="notice">${s.notes.length} 音 · ${pitchRange(s)} · ${val(s.bpm)} BPM · ${clock(s.duration)}</div>${s.warnings.map(w=>`<div class="notice orange">${esc(w)}</div>`).join('')}${overlap?'<div class="notice orange">這個選項有重疊音符，無法直接評分。請改選單一旋律聲部。</div>':''}<button class="btn" data-action="confirm-import" ${overlap?'disabled':''}>儲存並準備練習 ↗</button>`)}
async function confirmImport(){if(!parsedImport||state.busy)return;state.busy=true;try{const s={...parsedImport,title:$('import-title').value.trim()||parsedImport.title};if(hasOverlap(s.notes))throw new Error('請選擇沒有重疊音符的旋律聲部。');s.id=await db.saveScore(s);state.scores=await db.getScores();state.busy=false;closeModal();openSong(s.id);toast('旋律譜已保存。你可以接著選擇原唱、伴奏或吉他音檔。')}catch(e){state.busy=false;toast(e.message)}}
async function importAudio(file){if(!file||!state.song)return;if(file.size>50*1024*1024){toast('請使用 50 MB 以下的音檔，避免手機記憶體不足。');return;}try{state.song.audioNames={...state.song.audioNames,[state.audioKind]:file.name};if(state.song.format==='demo')state.song={...state.song,id:`my-${state.song.id}`,format:'imported-demo'}; // Built-ins keep their shipped melody; audio becomes a personal copy.
    // Move the selected blob to the personal ID if a built-in was copied.
    await db.saveAudio(state.song.id,state.audioKind,file);await db.saveScore(state.song);state.scores=await db.getScores();decodedCache=null;render();toast(db.getStorageStatus().persistent?'音檔已保存在這個裝置。':'音檔暫存在本頁，請另外保留原始檔。');}catch(e){toast(e.message)}}
function referenceImportModal(){showModal('從單音參考檔建立旋律',`<div class="notice orange">適用於清楚的獨唱、單音樂器錄音。完整原唱、吉他刷和弦與多樂器混音可能辨識錯誤；不能當作可靠的人聲分離工具。</div><p>程式會在這個裝置估計音符與時間，之後可以用你自己的伴奏來練。辨識不含歌詞；小於半音的錄音偏差會歸到最近音名，僅供建立初稿。</p><label class="btn upload-button" for="reference-upload">選擇音檔（8 分鐘內／50 MB 內）</label><input class="file-input" id="reference-upload" type="file" accept="audio/*,.mp3,.m4a,.wav"><p id="reference-progress" role="status"></p><button class="text-button" data-action="cancel-reference">取消</button>`)}
async function extractReference(file){
  if(!file)return;if(file.size>50*1024*1024){toast('音檔請小於 50 MB。');return;}
  const generation=++referenceGeneration;let jobWorker=null;
  try{
    state.busy=true;$('reference-progress').textContent='正在解碼音檔…';$('reference-upload').disabled=true;
    const context=await engine.ensureContext();if(generation!==referenceGeneration)return;
    const bytes=await file.arrayBuffer();if(generation!==referenceGeneration)return;
    const buffer=await context.decodeAudioData(bytes);if(generation!==referenceGeneration)return;
    if(buffer.duration>480)throw new Error('參考音檔請裁切為 8 分鐘以內。');
    const mono=new Float32Array(buffer.length);
    for(let c=0;c<buffer.numberOfChannels;c++){const channel=buffer.getChannelData(c);for(let i=0;i<mono.length;i++)mono[i]+=channel[i]/buffer.numberOfChannels;}
    jobWorker=new Worker('./reference-worker.js',{type:'module'});worker=jobWorker;
    jobWorker.onmessage=e=>{
      if(generation!==referenceGeneration){jobWorker.terminate();return;}
      if(e.data.type==='progress'){if($('reference-progress'))$('reference-progress').textContent=`裝置內分析中… ${Math.round(e.data.progress*100)}%`;return;}
      jobWorker.terminate();if(worker===jobWorker)worker=null;state.busy=false;
      if(e.data.type==='error'){toast(e.data.error);if($('reference-upload'))$('reference-upload').disabled=false;return;}
      if(!e.data.notes.length){toast('沒有找到足夠穩定的單音旋律。請改用旋律譜或更清楚的獨唱音檔。');closeModal();return;}
      parsedImport={title:file.name.replace(/\.[^.]+$/,''),notes:e.data.notes,bpm:80,duration:e.data.duration,format:'audio-estimate',warnings:e.data.warnings,parts:[],tracks:[]};state.importFile=file;showImportModal(parsedImport);
    };
    jobWorker.onerror=()=>{if(generation!==referenceGeneration)return;state.busy=false;jobWorker.terminate();if(worker===jobWorker)worker=null;toast('音檔辨識失敗，請改用旋律譜。');closeModal()};
    jobWorker.postMessage({samples:mono,sampleRate:buffer.sampleRate},[mono.buffer]);
  }catch(e){if(generation!==referenceGeneration)return;state.busy=false;jobWorker?.terminate();if(worker===jobWorker)worker=null;if($('reference-upload'))$('reference-upload').disabled=false;toast(e.name==='EncodingError'?'瀏覽器無法解碼此格式，請改用 WAV、MP3 或相容的 M4A。':e.message)}
}
async function restoreBackup(file){if(!file)return;if(file.size>20*1024*1024){toast('備份檔請小於 20 MB。');return;}try{const data=JSON.parse(await file.text());await db.importData(data);await loadData();closeModal();render();toast('備份已還原；音檔不在 JSON 備份內，請另外重新匯入。')}catch(e){toast(`無法還原備份：${e.message}`)}}
function retry(phrase=null){
  if(!state.reportScore){toast('請先重新開啟原歌曲或練習。');return;}
  if(state.report.kind==='song'){
    const s=allSongs().find(x=>x.id===state.report.scoreId);if(!s){toast('原歌曲已不在裝置內，請重新匯入。');return;}
    const saved=state.report.songSettings||{};
    state.song=s;state.phrase=phrase&&s.notes.some(n=>String(n.phrase)===String(phrase.id))?phrase:null;state.transpose=Number.isInteger(saved.transpose)&&saved.transpose>=-12&&saved.transpose<=12?saved.transpose:0;
    state.speed=[.5,.65,.8,1,1.1,1.2].includes(saved.speed)?saved.speed:1;state.audioKind=['synth','original','backing','guitar'].includes(saved.audioKind)?saved.audioKind:'synth';
    state.audioOffset=finite(saved.audioOffset)?Math.max(0,Math.min(1800,saved.audioOffset)):finite(s.audioOffset)?Math.max(0,Math.min(1800,s.audioOffset)):0;
    if(state.audioKind!=='synth'){state.transpose=0;state.speed=1;}decodedCache=null;go('songs');
  }else{
    const saved=state.report.exercise||{};state.route='practice';state.kind=saved.kind in kinds?saved.kind:'scale';
    state.root=finite(saved.root)?Math.max(43,Math.min(79,Math.round(saved.root))):60;state.bpm=finite(saved.bpm)?Math.max(40,Math.min(180,saved.bpm)):80;
    state.vowel=['mm','唇顫音','a','e','i','o','u','ma','me','mi','mo','mu','na','ni','nu','ba','bi','bu','da','di','du','ga','gi','gu'].includes(saved.vowel)?saved.vowel:kinds[state.kind].vowel;
    state.minutes=[.5,1,2,3,4,5].includes(saved.minutes)?saved.minutes:1;if(phrase)state.minutes=.5;
    render();window.scrollTo({top:0,behavior:'instant'});if(phrase)toast('已切換到相同訓練的短回合，方便加強。');
  }
}

document.addEventListener('click',async e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();go(route.dataset.route);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(state.busy&&!['cancel-reference','stop-session'].includes(a)){toast('正在處理音訊，請稍候。');return;}
  switch(a){
    case 'settings':settingsModal();break;
    case 'close-modal':closeModal();break;
    case 'exercise':state.planIndex=null;setExercise(el.dataset.kind);break;
    case 'range':go('range');break;
    case 'start-plan':startPlan();break;
    case 'plan-item':startPlan(Number(el.dataset.index));break;
    case 'next-plan':startPlan(state.planIndex+1,true);break;
    case 'start-session':await startSession();break;
    case 'stop-session':if(!cancelPreparation())await finishSession();break;
    case 'preview':await preview();break;
    case 'open-song':openSong(el.dataset.id);break;
    case 'recommended-song':el.dataset.id==='range-first'?setExercise('scale'):openSong(el.dataset.id,Number(el.dataset.transpose));break;
    case 'back-songs':state.song=null;state.phrase=null;stopPreview();render();break;
    case 'clear-phrase':state.phrase=null;stopPreview();render();break;
    case 'retry':retry();break;
    case 'retry-phrase':retry(state.report.phrases.find(p=>String(p.id)===el.dataset.id));break;
    case 'history-report':{const report=state.sessions.find(x=>x.id===el.dataset.id);state.report=report;state.reportScore=report.kind==='song'?allSongs().find(s=>s.id===report.scoreId):report.exercise?createExercise(report.exercise):null;state.planIndex=null;go('report');break;}
    case 'confirm-import':await confirmImport();break;
    case 'reference-import':referenceImportModal();break;
    case 'jianpu-import':openJianpu();break;
    case 'lrc-guide':toast('請開啟下方任一首歌曲，按「＋ 匯入 LRC」加入歌詞。');document.querySelector('.song-grid')?.scrollIntoView({behavior:'smooth',block:'start'});break;
    case 'lyric-phrase':practiceLyric(Number(el.dataset.index));break;
    case 'cancel-reference':referenceGeneration++;worker?.terminate();worker=null;state.busy=false;closeModal();break;
    case 'export':await exportBackup();break;
    case 'delete-song':showModal('刪除這首歌曲？',`<p>將刪除「${esc(state.song.title)}」及它在這個裝置的參考音檔。已完成的分析紀錄會保留。</p><button class="btn danger" data-action="confirm-delete">刪除歌曲與音檔</button><button class="btn ghost" data-action="close-modal" style="margin-left:10px">保留</button>`);break;
    case 'confirm-delete':await db.deleteScore(state.song.id);state.scores=await db.getScores();state.song=null;decodedCache=null;closeModal();render();toast('歌曲已刪除。');break;
    case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;closeModal();}break;
  }
});
document.addEventListener('change',async e=>{const el=e.target;
  if(state.session||state.busy){if(el.id!=='reference-upload'){toast('請先結束目前的練習。');return;}}
  switch(el.id){
    case 'root-select':stopPreview();state.root=Number(el.value);drawChart();break;
    case 'vowel-select':stopPreview();state.vowel=el.value;drawChart();break;
    case 'bpm-input':stopPreview();state.bpm=Math.max(40,Math.min(180,Number(el.value)||80));el.value=state.bpm;render();break;
    case 'minutes-select':stopPreview();state.minutes=Number(el.value);render();break;
    case 'transpose-select':stopPreview();state.transpose=Number(el.value);drawChart();break;
    case 'speed-select':stopPreview();state.speed=Number(el.value);render();break;
    case 'audio-kind':stopPreview();state.audioKind=el.value;if(state.audioKind!=='synth'){state.transpose=0;state.speed=1}render();break;
    case 'audio-offset':state.audioOffset=Math.max(0,Math.min(1800,Number(el.value)||0));state.song.audioOffset=state.audioOffset;groupNotesByLyrics(state.song);state.phrase=null;await db.saveScore(state.song);render();break;
    case 'lrc-offset':state.song.lyrics.offsetMs=Math.max(-10000,Math.min(10000,Number(el.value)||0));groupNotesByLyrics(state.song);state.phrase=null;await db.saveScore(state.song);render();break;
    case 'lrc-upload':await importSongLyrics(el.files[0]);break;
    case 'score-upload':await importScore(el.files[0]);break;
    case 'audio-upload':await importAudio(el.files[0]);break;
    case 'reference-upload':await extractReference(el.files[0]);break;
    case 'backup-upload':await restoreBackup(el.files[0]);break;
    case 'import-part':await importScore(state.importFile,{partId:el.value});break;
    case 'import-voice':await importScore(state.importFile,{partId:parsedImport.selectedPart,voice:el.value});break;
    case 'import-track':await importScore(state.importFile,{trackIndex:Number(el.value)});break;
    case 'tolerance-setting':state.settings.tolerance=Number(el.value);await db.setSetting('preferences',state.settings);break;
    case 'latency-setting':state.settings.latencyMs=Number(el.value);await db.setSetting('preferences',state.settings);break;
    case 'guide-setting':state.settings.guide=el.checked;await db.setSetting('preferences',state.settings);break;
    case 'metronome-setting':state.settings.metronome=el.checked;await db.setSetting('preferences',state.settings);break;
  }
});
document.addEventListener('input',e=>{if(e.target.id==='latency-setting')$('latency-label').textContent=e.target.value+' 毫秒'});
$('settings-button').addEventListener('click',()=>{if(state.session||state.busy||monitorController?.isBusy){toast('請先結束目前的練習。');return;}settingsModal()});
$('modal').addEventListener('click',e=>{if(e.target===$('modal')&&!state.busy)closeModal()});
$('modal').addEventListener('cancel',e=>{if(state.busy){e.preventDefault();toast('分析尚在進行，可以按取消來停止。')}});
window.addEventListener('resize',()=>drawChart());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPreview();if(state.session){finishSession(true);toast('切換到背景，練習已停止並分析目前收到的聲音。')}else cancelPreparation('切換到背景，麥克風準備已取消。');}});
window.addEventListener('pagehide',()=>{preparationGeneration++;referenceGeneration++;releaseSession(state.session);worker?.terminate();monitorController?.destroy();jianpuController?.destroy()});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(tabs.some(([r])=>r===route))go(route)});
async function loadData(){const [sessions,scores,range,settings]=await Promise.all([db.getSessions(500),db.getScores(),db.getSetting('range'),db.getSetting('preferences',{})]);state.sessions=sessions;state.scores=scores;state.range=range;state.settings={...state.settings,...settings};}
async function boot(){try{await loadData();const initial=location.hash.slice(1);state.route=tabs.some(([r])=>r===initial)?initial:'home';render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('connection').title='離線快取已準備完成'}).catch(()=>{$('connection').title='此瀏覽器未完成離線快取，請保持連線'})}}catch(e){$('main').innerHTML='<div class="empty">無法載入資料，請重新整理頁面。</div>';toast(e.message)}}
boot();
